import { GoogleGenAI, Type, Schema } from "@google/genai";
import { GeneratedQuizResponse, ExamType, LessonPlan, SlideDeck } from "../types";

// Initialize the client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const researchTopic = async (query: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: query,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "Você é um assistente pedagógico útil. Forneça resumos claros, precisos e educativos para professores. Use formatação Markdown.",
      },
    });

    const text = response.text || "Não foi possível gerar uma resposta.";
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    // Extract sources if available
    const sources = groundingChunks
      .filter((chunk: any) => chunk.web?.uri && chunk.web?.title)
      .map((chunk: any) => ({
        title: chunk.web.title,
        uri: chunk.web.uri
      }));

    return { text, sources };
  } catch (error) {
    console.error("Error researching topic:", error);
    throw error;
  }
};

export const generateExam = async (topic: string, gradeLevel: string, questionCount: number, type: ExamType): Promise<GeneratedQuizResponse> => {
  try {
    let prompt = '';
    let schema: Schema = { type: Type.OBJECT, properties: {} };

    if (type === 'MULTIPLE_CHOICE') {
      prompt = `Crie uma prova de MÚLTIPLA ESCOLHA sobre o tema: "${topic}". 
      Nível escolar: ${gradeLevel}. 
      Quantidade de questões: ${questionCount}.
      Retorne apenas JSON válido.`;

      schema = {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING, description: "Título criativo para a prova" },
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                questionText: { type: Type.STRING },
                options: { 
                  type: Type.ARRAY, 
                  items: { type: Type.STRING },
                  description: "Exatamente 4 opções de resposta"
                },
                correctOptionIndex: { type: Type.INTEGER, description: "Índice (0-3) da resposta correta" },
                explanation: { type: Type.STRING, description: "Breve explicação do porquê a resposta está correta" }
              },
              required: ["questionText", "options", "correctOptionIndex", "explanation"]
            }
          }
        },
        required: ["title", "questions"]
      };
    } else {
      // OPEN ENDED
      prompt = `Crie uma prova de QUESTÕES ABERTAS (Dissertativas) sobre o tema: "${topic}". 
      Nível escolar: ${gradeLevel}. 
      Quantidade de questões: ${questionCount}.
      Para cada questão, forneça a pergunta e uma resposta esperada (gabarito) detalhada para o professor.
      Retorne apenas JSON válido.`;

      schema = {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING, description: "Título criativo para a prova" },
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                questionText: { type: Type.STRING, description: "O enunciado da questão dissertativa" },
                expectedAnswer: { type: Type.STRING, description: "A resposta ideal ou critérios de correção para o professor" }
              },
              required: ["questionText", "expectedAnswer"]
            }
          }
        },
        required: ["title", "questions"]
      };
    }

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema
      }
    });

    if (response.text) {
      const parsed = JSON.parse(response.text) as GeneratedQuizResponse;
      // Inject the type back into the response so the UI knows how to render it
      return { ...parsed, type };
    }
    throw new Error("No data returned");
  } catch (error) {
    console.error("Error generating exam:", error);
    throw error;
  }
};

