      prompt = `Crie uma Lista de EXERCÍCIOS DE FIXAÇÃO sobre o tema: "${topic}". 
      Nível escolar: ${gradeLevel}. 
      Quantidade de questões: ${questionCount}.
      Foco: Reforço escolar e prática.
      Retorne apenas JSON válido.`;

      schema = {
