        properties: {
          title: { type: Type.STRING, description: "Título descritivo da lista de exercícios" },
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                questionText: { type: Type.STRING },
                options: { 
                  type: Type.ARRAY, 
                  items: { type: Type.STRING },
                  description: "Exatamente 4 opções"
                },
