      prompt = `Crie uma Lista de EXERCÍCIOS PRÁTICOS (Dissertativos) sobre o tema: "${topic}". 
      Nível escolar: ${gradeLevel}. 
      Quantidade de questões: ${questionCount}.
      Foco: Desenvolvimento de raciocínio e prática.
