import React, { useState } from 'react';
import { generateExercises } from '../../services/geminiService';
import { GeneratedQuizResponse, ExamType, ArchivedExam } from '../../types';
import { PenTool, CheckCircle, Save, RefreshCw, AlertTriangle, FileText, Download, Loader2, ListChecks, AlignLeft, User, Book, Archive, RotateCcw } from 'lucide-react';

interface ExerciseCreatorProps {
  onArchiveExercise?: (exam: ArchivedExam) => void;
}

export const ExerciseCreatorView: React.FC<ExerciseCreatorProps> = ({ onArchiveExercise }) => {
  const [topic, setTopic] = useState('');
  const [gradeLevel, setGradeLevel] = useState('Ensino Médio');
  const [questionCount, setQuestionCount] = useState(5);
  const [examType, setExamType] = useState<ExamType>('MULTIPLE_CHOICE');

  // Header Info State
  const [courseUnit, setCourseUnit] = useState('');
  const [teacherName, setTeacherName] = useState('');

  const [isGenerating, setIsGenerating] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [generatedExercises, setGeneratedExercises] = useState<GeneratedQuizResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isArchived, setIsArchived] = useState(false);

  const handleReset = () => {
    setGeneratedExercises(null);
    setTopic('');
    setIsArchived(false);
    setError(null);
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsGenerating(true);
    setError(null);
    setGeneratedExercises(null);
    setIsArchived(false);

    try {
      const result = await generateExercises(topic, gradeLevel, questionCount, examType);
      setGeneratedExercises(result);
    } catch (err) {
      setError("Falha ao gerar os exercícios. Tente novamente.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleArchive = () => {
    if (!generatedExercises || !onArchiveExercise) return;

    const exerciseToArchive: ArchivedExam = {
      ...generatedExercises,
      title: `[Exercício] ${generatedExercises.title}`, // Add tag to distinguish
      id: Date.now().toString(),
      createdAt: new Date().toISOString(),
      courseUnit,
      teacherName,
      gradeLevel
    };

    onArchiveExercise(exerciseToArchive);
    setIsArchived(true);
  };

  const handleDownload = () => {
    if (!generatedExercises) return;

    setIsDownloading(true);
    const element = document.getElementById('exercise-content');

    if (element && typeof html2pdf !== 'undefined') {
      const opt = {
        margin: [10, 10, 10, 10], // top, left, bottom, right
        filename: `exercicios_${generatedExercises.title.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };

      html2pdf()
        .set(opt)
        .from(element)
        .save()
        .then(() => setIsDownloading(false))
        .catch((err: any) => {
          console.error("PDF generation failed", err);
          setIsDownloading(false);
          // Fallback to print if library fails
          window.print();
        });
    } else {
      // Fallback
      window.print();
      setIsDownloading(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 h-full">
      {/* Configuration Panel */}
      <div className="lg:col-span-1 no-print">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 sticky top-6 max-h-[calc(100vh-3rem)] overflow-y-auto">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
                <div className="p-2 bg-cyan-100 rounded-lg text-cyan-600">
                <PenTool size={24} />
                </div>
                <h2 className="text-xl font-bold text-gray-800">Gerador de Exercícios</h2>
            </div>
            {generatedExercises && (
                <button 
                    onClick={handleReset}
                    className="text-gray-400 hover:text-cyan-600 transition-colors"
                    title="Limpar e Criar Novo"
                >
                    <RotateCcw size={20} />
                </button>
            )}
          </div>

          <form onSubmit={handleGenerate} className="space-y-5">
            {/* Header Information Section */}
            <div className="p-4 bg-gray-50 rounded-lg border border-gray-200 space-y-4">
              <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider">Cabeçalho (Opcional)</h3>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-2">
                  <Book size={14} /> Disciplina
                </label>
                <input
                  type="text"
                  value={courseUnit}
                  onChange={(e) => setCourseUnit(e.target.value)}
                  className="w-full p-2 border border-gray-300 rounded-md focus:ring-1 focus:ring-cyan-500 text-sm"
                  placeholder="Ex: Matemática"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-2">
                  <User size={14} /> Professor(a)
                </label>
                <input
                  type="text"
                  value={teacherName}
                  onChange={(e) => setTeacherName(e.target.value)}
                  className="w-full p-2 border border-gray-300 rounded-md focus:ring-1 focus:ring-cyan-500 text-sm"
                  placeholder="Ex: Prof. Ana"
                />
              </div>
            </div>

            <hr className="border-gray-200" />

            {/* Exam Content Section */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Tópico ou Assunto
              </label>
              <textarea
                required
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-cyan-500 focus:border-cyan-500 min-h-[80px]"
                placeholder="Ex: Frações, Concordância Verbal, Tabela Periódica..."
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Tipo de Atividade
              </label>
              <div className="grid grid-cols-2 gap-3">
                <button
                  type="button"
                  onClick={() => setExamType('MULTIPLE_CHOICE')}
                  className={`flex flex-col items-center justify-center p-3 rounded-lg border transition-all ${
                    examType === 'MULTIPLE_CHOICE'
                      ? 'bg-cyan-50 border-cyan-500 text-cyan-700'
                      : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  <ListChecks size={24} className="mb-1" />
                  <span className="text-xs font-medium">Múltipla Escolha</span>
                </button>
                <button
                  type="button"
                  onClick={() => setExamType('OPEN_ENDED')}
                  className={`flex flex-col items-center justify-center p-3 rounded-lg border transition-all ${
                    examType === 'OPEN_ENDED'
                      ? 'bg-cyan-50 border-cyan-500 text-cyan-700'
                      : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  <AlignLeft size={24} className="mb-1" />
                  <span className="text-xs font-medium">Dissertativa</span>
                </button>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Nível
                </label>
                <select
                  value={gradeLevel}
                  onChange={(e) => setGradeLevel(e.target.value)}
                  className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-cyan-500 bg-white text-sm"
                >
                  <option>Fundamental I</option>
                  <option>Fundamental II</option>
                  <option>Ensino Médio</option>
                  <option>Ensino Superior</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Qtd. Questões
                </label>
                <input
                  type="number"
                  min="1"
                  max="20"
                  value={questionCount}
                  onChange={(e) => setQuestionCount(Number(e.target.value))}
                  className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-cyan-500 text-sm"
                />
              </div>
