import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { DashboardView } from './components/views/DashboardView';
import { ResearchView } from './components/views/ResearchView';
import { ExamCreatorView } from './components/views/ExamCreatorView';
import { ExerciseCreatorView } from './components/views/ExerciseCreatorView';
import { GradebookView } from './components/views/GradebookView';
import { LessonPlanView } from './components/views/LessonPlanView';
import { SlideGeneratorView } from './components/views/SlideGeneratorView';
import { ViewState, Student, ArchivedExam } from './types';

// Initial Mock Data (Optional, can start empty)
const INITIAL_STUDENTS: Student[] = [
  { id: '1', name: 'Ana Silva', avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Ana', grades: { math: 8.5, history: 9.0, science: 7.5 }, attendance: 95 },
  { id: '2', name: 'Bruno Costa', avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Bruno', grades: { math: 6.0, history: 7.5, science: 8.0 }, attendance: 88 },
];

function App() {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);

  // Global State
  const [students, setStudents] = useState<Student[]>(INITIAL_STUDENTS);
  const [archivedExams, setArchivedExams] = useState<ArchivedExam[]>([]);
  const [selectedExam, setSelectedExam] = useState<ArchivedExam | null>(null);

  // Handlers
  const handleAddStudent = (newStudent: Student) => {
    setStudents(prev => [...prev, newStudent]);
  };

  const handleUpdateStudent = (updatedStudent: Student) => {
    setStudents(prev => prev.map(s => s.id === updatedStudent.id ? updatedStudent : s));
  };

  const handleArchiveExam = (exam: ArchivedExam) => {
    setArchivedExams(prev => [exam, ...prev]);
  };

  const handleViewExam = (exam: ArchivedExam) => {
    setSelectedExam(exam);
    setCurrentView(ViewState.EXAMS);
  };

  const handleSidebarChange = (view: ViewState) => {
    if (view !== ViewState.EXAMS) {
        setSelectedExam(null);
    }
    setCurrentView(view);
  };

  const renderContent = () => {
    switch (currentView) {
      case ViewState.DASHBOARD:
        return (
          <DashboardView 
            changeView={setCurrentView} 
            students={students}
            archivedExams={archivedExams}
            onAddStudent={handleAddStudent}
            onViewExam={handleViewExam}
          />
        );
      case ViewState.RESEARCH:
        return <ResearchView />;
      case ViewState.LESSON_PLAN:
        return <LessonPlanView />;
      case ViewState.SLIDES:
        return <SlideGeneratorView />;
      case ViewState.EXERCISES:
        return (
          <ExerciseCreatorView 
            onArchiveExercise={handleArchiveExam}
          />
        );
      case ViewState.EXAMS:
        return (
          <ExamCreatorView 
            onArchiveExam={handleArchiveExam}
            initialExam={selectedExam}
          />
        );
      case ViewState.GRADES:
        return (
          <GradebookView 
            students={students}
            onUpdateStudent={handleUpdateStudent}
          />
        );
      default:
        return (
          <DashboardView 
            changeView={setCurrentView} 
            students={students}
            archivedExams={archivedExams}
            onAddStudent={handleAddStudent}
            onViewExam={handleViewExam}
          />
        );
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-900 selection:bg-indigo-100 selection:text-indigo-800">
      <Sidebar currentView={currentView} setView={handleSidebarChange} />

      <main className="flex-1 ml-64 p-8 overflow-y-auto max-w-[1920px] transition-all duration-300">
        <div className="max-w-7xl mx-auto h-full">
          {renderContent()}
        </div>
      </main>
    </div>
  );
}

export default App;

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { GeneratedQuizResponse, ExamType, LessonPlan, SlideDeck, GeneratedExerciseResponse, ExerciseType, ChatMessage } from "../types";

// Initialize the client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const researchTopic = async (query: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: query,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "Você é um especialista pedagógico acadêmico. Forneça resumos aprofundados, com rigor técnico e fontes confiáveis. Use formatação Markdown.",
      },
    });

    const text = response.text || "Não foi possível gerar uma resposta.";
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    // Extract sources if available
    const sources = groundingChunks
      .filter((chunk: any) => chunk.web?.uri && chunk.web?.title)
      .map((chunk: any) => ({
        title: chunk.web.title,
        uri: chunk.web.uri
      }));

    return { text, sources };
  } catch (error) {
    console.error("Error researching topic:", error);
    throw error;
  }
};

