    ${specificTopics}

    DIRETRIZES CRUCIAIS:
    1. NÃO FAÇA APENAS LISTAS DE TÓPICOS. Você deve EXPLICAR o conteúdo.
    2. Cada slide deve ser uma "miniaula" sobre aquele ponto.
    3. Use frases completas, definições, exemplos práticos, contextos históricos ou aplicações reais.
    4. O conteúdo deve ser substancial (mínimo 30-40 palavras por ponto), pronto para o aluno ler e aprender.
    5. Distribua os Tópicos Específicos fornecidos ao longo dos slides de forma lógica.`;

    const schema: Schema = {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING, description: "O tema principal (pode ser ajustado para ser mais atrativo)" },
        gradeLevel: { type: Type.STRING },
        slides: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING, description: "Título impactante do slide" },
              content: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING },
                description: "Parágrafos curtos ou frases completas explicando o conceito detalhadamente. Não use apenas palavras-chave."
              },
              imageDescription: { type: Type.STRING, description: "Descrição visual detalhada para compor o slide (ex: paisagem, diagrama, objeto em fundo branco)" },
              speakerNotes: { type: Type.STRING, description: "Roteiro detalhado para a fala do professor, expandindo os tópicos e dando exemplos extras" }
            },
            required: ["title", "content", "imageDescription", "speakerNotes"]
          }
        }
      },
      required: ["topic", "gradeLevel", "slides"]
    };

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as SlideDeck;
    }
    throw new Error("No data returned for slide deck");
  } catch (error) {
    console.error("Error generating slides:", error);
    throw error;
  }
};

