                      className="flex-1 bg-transparent border-none focus:ring-0 text-sm max-h-32 min-h-[44px] py-3 resize-none custom-scrollbar placeholder:text-gray-400"
                      rows={1}
                  />

                  <button 
                      onClick={handleSendMessage}
